# owner: platform
"""Weekly timesheet lines, one per worker."""

from typing import Dict, Iterable, List, Tuple

from hourglass.models import Shift

Totals = Dict[str, Tuple[int, int]]

def _tally(shifts: List[Shift]) -> Totals:
    tally = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker")
        count, mins = tally.get(shift.worker, (0, 0))
        mins += shift.span.minutes
        tally[shift.worker] = (count + 1, mins)
    return tally

def _busyness(item) -> tuple:
    name, (count, mins) = item
    return (-mins, -count, name)

def _format_row(name: str, count: int, mins: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    return f"{name}: {count} {noun}, {mins / 60:.1f} hours"

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    shifts = list(shifts)
    if not shifts:
        raise ValueError("no shifts to total")
    rows = sorted(_tally(shifts).items(), key=_busyness)
    return [_format_row(name, *stat) for name, stat in rows]
